<template><div class="app-container"><el-button type="primary" icon="Plus" @click="openAdd" v-hasPermi="['research:review:add']">新增复盘</el-button><el-table v-loading="loading" :data="rows" class="mt12"><el-table-column prop="sourceType" label="来源" width="100"/><el-table-column prop="sourceId" label="来源ID" width="100"/><el-table-column prop="rating" label="评价" width="100"/><el-table-column prop="reason" label="原因" show-overflow-tooltip/><el-table-column prop="lesson" label="经验总结" show-overflow-tooltip/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="remove(row)" v-hasPermi="['research:review:remove']">删除</el-button></template></el-table-column></el-table><pagination v-show="total" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/><el-dialog v-model="dialog" title="新增复盘" width="560px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="来源类型" prop="sourceType"><el-select v-model="form.sourceType"><el-option label="回测" value="backtest"/><el-option label="模拟交易" value="simulation"/></el-select></el-form-item><el-form-item label="来源ID" prop="sourceId"><el-input-number v-model="form.sourceId" :min="1"/></el-form-item><el-form-item label="评价" prop="rating"><el-select v-model="form.rating"><el-option label="正确" value="good"/><el-option label="错误" value="bad"/><el-option label="待确认" value="uncertain"/></el-select></el-form-item><el-form-item label="原因"><el-input v-model="form.reason" type="textarea"/></el-form-item><el-form-item label="经验总结"><el-input v-model="form.lesson" type="textarea"/></el-form-item><el-form-item label="标签"><el-input v-model="form.tags"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="ResearchReview">import { addReview, delReview, listReview } from '@/api/project-research/research'
const { proxy }=getCurrentInstance();const loading=ref(false),dialog=ref(false),total=ref(0),rows=ref([]),formRef=ref();const query=reactive({pageNum:1,pageSize:10});const form=reactive({});const rules={sourceType:[{required:true,message:'请选择来源'}],sourceId:[{required:true,message:'请输入来源ID'}],rating:[{required:true,message:'请选择评价'}]};function load(){loading.value=true;listReview(query).then(r=>{rows.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)}function openAdd(){Object.assign(form,{sourceType:'backtest',sourceId:undefined,rating:'good',reason:'',lesson:'',tags:''});dialog.value=true}function save(){formRef.value.validate(v=>{if(v)addReview(form).then(()=>{proxy.$modal.msgSuccess('保存成功');dialog.value=false;load()})})}function remove(r){proxy.$modal.confirm('确认删除该复盘吗？').then(()=>delReview(r.id)).then(load)}load()</script><style scoped>.mt12{margin-top:12px}</style>
